import 'package:flutter/material.dart';
void main()=>runApp(const AdminApp());
class AdminApp extends StatelessWidget{const AdminApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Raksha Graha Admin',theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const Dashboard());}
class Dashboard extends StatelessWidget{const Dashboard({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Raksha Graha Admin'),actions:[IconButton(onPressed:(){},icon:const Icon(Icons.notifications_none))]),body:GridView.count(crossAxisCount:2,padding:const EdgeInsets.all(16),crossAxisSpacing:12,mainAxisSpacing:12,children:[_card(c,'Users',Icons.people),_card(c,'Customer Chats',Icons.chat),_card(c,'Customer-Customer Chat',Icons.lock),_card(c,'Daily Content',Icons.today),_card(c,'Festival',Icons.celebration),_card(c,'Notifications',Icons.notifications),_card(c,'Suggestions',Icons.feedback),_card(c,'Admin Management',Icons.admin_panel_settings)]));}
Widget _card(BuildContext c,String t,IconData i)=>Card(child:InkWell(onTap:(){},child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(i,size:34),const SizedBox(height:8),Text(t,textAlign:TextAlign.center)]))));}
